{"code":"import pandas as pd, statsmodels.api as sm
D=pd.read_csv('data/explore.csv'); cols=['canopy_cover','soil_moisture','elevation_m','road_dist_km','leaf_litter','temperature_c','slope_deg','nitrate','grazing_index','rainfall_mm']
for x in cols:
 z=D[['species_richness','region',x]].dropna(); X=pd.concat([z[[x]],pd.get_dummies(z.region,drop_first=True,dtype=float)],axis=1); m=sm.OLS(z.species_richness,sm.add_constant(X)).fit()
 print(x,round(m.params[x],3),round(m.pvalues[x],5),round(m.rsquared,3))"}
